protected void init()
{
    api = XAPI_APIS::GetLocations;
    super();
}

protected void postRun()
{
    System.Text.RegularExpressions.Regex regex;
    System.Text.RegularExpressions.Match match;

    if (!responseText)
    {
        return;
    }

    regex = new System.Text.RegularExpressions.Regex("\"RecId\"\\s*:\\s*(\\d+)");
    match = regex.Match(responseText);

    logKey = "DelPointRecId";
    if (match.get_Success())
    {
        logValue = match.Groups.get_Item(1).get_Value();
    }
}

protected str body()
{
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>',  curExt());
    configMap.insert('<accountNum>',  XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount'));

    return this.prepareBody(configMap);
}
